fn get_min_val(a: &Vec<i8>) -> i8 {
    // Since `a` is guaranteed non‐empty, we can initialize with the first element.
    let mut min_val = a[0];
    for &x in &a[1..] {
        if x < min_val {
            min_val = x;
        }
    }
    min_val
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Similarly, initialize with the first element.
    let mut max_val = a[0];
    for &x in &a[1..] {
        if x > max_val {
            max_val = x;
        }
    }
    max_val
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // Assume `a` is non-empty and 0 <= q <= 100.
    // Sort the data:
    a.sort_unstable();

    let n = a.len();
    // Compute index = floor((q / 100) * (n-1))
    // Casting q to usize is safe under the assumption 0 <= q <= 100.
    let q_usize = q as usize;
    let idx = (q_usize * (n - 1)) / 100;

    a[idx]
}

